class Session implements Disposable {
  #socket: Socket;
  constructor(addr: string) { this.#socket = connect(addr); }
  [Symbol.dispose](): void { this.#socket.close(); }   // runs at scope exit
}
function handle(addr: string): void {
  using session = new Session(addr);        // disposed on return or throw
  session.roundTrip();
}
const cache = new WeakMap<Session, WeakRef<Expensive>>();   // non-owning edges
